import{_ as e,o as i,c as a,a2 as o}from"./chunks/framework.BXzK3EA4.js";const h=JSON.parse('{"title":"Configuration Guide","description":"","frontmatter":{},"headers":[],"relativePath":"guide/configuration.md","filePath":"guide/configuration.md"}'),n={name:"guide/configuration.md"};function r(s,t,l,d,c,u){return i(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="configuration-guide" tabindex="-1">Configuration Guide <a class="header-anchor" href="#configuration-guide" aria-label="Permalink to &quot;Configuration Guide&quot;">​</a></h1><p>FOSSBilling uses environment variables for configuration. When running via Docker, these are typically defined in your <code>docker-compose.yml</code> or a <code>.env</code> file.</p><hr><h2 id="⚙️-core-configuration-variables" tabindex="-1">⚙️ Core Configuration Variables <a class="header-anchor" href="#⚙️-core-configuration-variables" aria-label="Permalink to &quot;⚙️ Core Configuration Variables&quot;">​</a></h2><p>These variables control the connection to essential services and core security settings.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Variable</th><th style="text-align:left;">Default</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>APP_ENV</code></td><td style="text-align:left;"><code>development</code></td><td style="text-align:left;">Environment mode (<code>production</code>, <code>development</code>, <code>test</code>)</td></tr><tr><td style="text-align:left;"><code>PORT</code></td><td style="text-align:left;"><code>8080</code></td><td style="text-align:left;">The port the Go API server listens on</td></tr><tr><td style="text-align:left;"><code>DATABASE_URL</code></td><td style="text-align:left;">-</td><td style="text-align:left;">PostgreSQL DSN: <code>postgres://user:pass@host:5432/db?sslmode=disable</code></td></tr><tr><td style="text-align:left;"><code>REDIS_URL</code></td><td style="text-align:left;">-</td><td style="text-align:left;">Redis DSN: <code>redis://host:6379</code></td></tr><tr><td style="text-align:left;"><code>JWT_SECRET</code></td><td style="text-align:left;">-</td><td style="text-align:left;">A 32+ character string used to sign authentication tokens</td></tr><tr><td style="text-align:left;"><code>APP_URL</code></td><td style="text-align:left;"><code>http://localhost:8080</code></td><td style="text-align:left;">The base URL where the API is publicly accessible</td></tr><tr><td style="text-align:left;"><code>DEFAULT_CURRENCY</code></td><td style="text-align:left;"><code>USD</code></td><td style="text-align:left;">Default 3-letter ISO code for pricing</td></tr></tbody></table><hr><h2 id="🔒-security-configuration" tabindex="-1">🔒 Security Configuration <a class="header-anchor" href="#🔒-security-configuration" aria-label="Permalink to &quot;🔒 Security Configuration&quot;">​</a></h2><p>It is critical to change the <code>JWT_SECRET</code> in production. If this key is compromised, attackers can forge authentication tokens for any user or administrator.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Generate a secure secret</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rand</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -base64</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 32</span></span></code></pre></div><hr><h2 id="📧-mailer-configuration" tabindex="-1">📧 Mailer Configuration <a class="header-anchor" href="#📧-mailer-configuration" aria-label="Permalink to &quot;📧 Mailer Configuration&quot;">​</a></h2><p>FOSSBilling supports multiple mail transports (SMTP, Sendmail). These are currently configured within the system settings database, but can be overridden via environment variables in future updates.</p><ul><li><strong>SMTP Host:</strong> Server address for outgoing mail.</li><li><strong>SMTP Port:</strong> 587 (TLS) or 465 (SSL).</li><li><strong>Authentication:</strong> Username and password for your mail provider.</li></ul><hr><h2 id="🛠️-infrastructure-tuning" tabindex="-1">🛠️ Infrastructure Tuning <a class="header-anchor" href="#🛠️-infrastructure-tuning" aria-label="Permalink to &quot;🛠️ Infrastructure Tuning&quot;">​</a></h2><p>For high-traffic deployments, you can tune the following:</p><ul><li><strong>DB Max Connections:</strong> Managed via <code>pgxpool</code> configuration in code.</li><li><strong>Redis Eviction Policy:</strong> Recommended <code>allkeys-lru</code> for caching efficiency.</li><li><strong>Worker Concurrency:</strong> Controls how many background tasks the worker processes simultaneously.</li></ul>`,18)])])}const f=e(n,[["render",r]]);export{h as __pageData,f as default};
